#[app::state(emits = Event)]
pub struct Board {
    elements: UnorderedMap<String, Element>,
}

#[app::logic]
impl Board {
    pub fn add_element(&mut self, el: Element) {
        let id = el.id.clone();
        self.elements.insert(id.clone(), el);
        app::emit!(Event::ElementAdded(id));
    }
}
